package com.henson.jarvis.phone;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.speech.*;import android.webkit.*;import android.view.WindowManager;import org.json.*;import java.util.*;import java.util.concurrent.*;
public final class MainActivity extends Activity {
 private WebView web;private LocalSite site;private OpenAIClient ai;private final ExecutorService worker=Executors.newSingleThreadExecutor();private SpeechRecognizer speech;private String speechId,pendingMicrophoneId;private PermissionRequest pendingPermission;private volatile boolean foreground;private boolean welcomeShowing,authFinishing;
 public void onCreate(Bundle saved){super.onCreate(saved);try{ai=new OpenAIClient(new TokenVault(this));site=new LocalSite(getAssets(),uri->{ai.stageCallback(uri);runOnUiThread(()->{state();if(foreground)finishSignIn();});});web=new WebView(this);web.setBackgroundColor(0xff050b13);setContentView(web);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setMediaPlaybackRequiresUserGesture(false);web.addJavascriptInterface(new Bridge(),"JarvisNative");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String url=request.getUrl().toString();if(url.startsWith(site.origin()+"/"))return false;if(request.isForMainFrame()&&"https".equals(request.getUrl().getScheme()))startActivity(new Intent(Intent.ACTION_VIEW,request.getUrl()));return true;}public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){String url=request.getUrl().toString();if(!url.startsWith(site.origin()+"/")&&!url.startsWith("blob:"))return new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));return null;}});web.setWebChromeClient(new WebChromeClient(){public void onPermissionRequest(PermissionRequest request){runOnUiThread(()->{if(!trusted()||!(request.getOrigin().getScheme()+"://"+request.getOrigin().getAuthority()).equals(site.origin())){request.deny();return;}if(!Arrays.asList(request.getResources()).contains(PermissionRequest.RESOURCE_AUDIO_CAPTURE)){request.deny();return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)request.grant(new String[]{PermissionRequest.RESOURCE_AUDIO_CAPTURE});else{if(pendingPermission!=null)pendingPermission.deny();pendingPermission=request;requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},7);}});}public void onPermissionRequestCanceled(PermissionRequest request){if(pendingPermission==request)pendingPermission=null;}public boolean onJsConfirm(WebView view,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("Confirm",(d,w)->result.confirm()).setNegativeButton("Cancel",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}});web.loadUrl(site.origin()+"/");}catch(Exception e){new AlertDialog.Builder(this).setMessage("JARVIS could not start its private local interface. Restart the app.").setPositiveButton("Close",(d,w)->finish()).show();}}
 private boolean trusted(){return web!=null&&site!=null&&web.getUrl()!=null&&web.getUrl().startsWith(site.origin()+"/");}
 private void result(String id,JSONObject body){runOnUiThread(()->{if(trusted())web.evaluateJavascript("window.jarvisNativeResult?.("+JSONObject.quote(id)+","+body.toString()+");",null);});}
 private void error(String id,Exception e){try{result(id,new JSONObject().put("error",e.getMessage()==null?"Native request failed.":e.getMessage()));}catch(JSONException ignored){}}
 private void state(){runOnUiThread(()->{if(trusted())web.evaluateJavascript("window.dispatchEvent(new Event('jarvis-account-changed'));",null);});}
 private void connect(){worker.execute(()->{try{if(ai.hasStagedCallback()){runOnUiThread(this::finishSignIn);return;}JSONObject accounts=ai.savedAccounts();if(accounts.length()==0){runOnUiThread(()->authorize(null));return;}ArrayList<String> ids=new ArrayList<>(),labels=new ArrayList<>();for(Iterator<String> keys=accounts.keys();keys.hasNext();){String id=keys.next();ids.add(id);labels.add(accounts.getJSONObject(id).optString("email","ChatGPT account")+" · "+id.substring(Math.max(0,id.length()-6)));}labels.add("Use another ChatGPT account");runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Use your ChatGPT plan").setItems(labels.toArray(new String[0]),(d,index)->authorize(index<ids.size()?ids.get(index):null)).show());}catch(Exception e){error("account",e);}});}
 private void authorize(String selected){new AlertDialog.Builder(this).setTitle("Continue with ChatGPT").setMessage("JARVIS will use your existing ChatGPT plan allowance. It has no paid API fallback. Keep extra-credit use and automatic credit purchases disabled in ChatGPT to avoid additional charges. Your ChatGPT login opens securely in your browser; tokens stay encrypted in this app.").setPositiveButton("Continue",(d,w)->worker.execute(()->{try{notice("Checking the OpenAI connection…");ai.checkLoginServer();String url=ai.authorize(selected,site.origin()+"/auth/callback");runOnUiThread(()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url))));}catch(Exception e){error("account",e);}})).setNegativeButton("Cancel",null).show();}
 public final class Bridge {
  @JavascriptInterface public void request(String id,String method,String payload){if(method==null||id==null||id.length()>100||payload==null||payload.length()>90000)return;runOnUiThread(()->{if(!trusted())return;if(method.equals("microphone")){if(!foreground){error(id,new Exception("Return to JARVIS before enabling the microphone."));return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED){try{result(id,new JSONObject().put("granted",true));}catch(JSONException e){error(id,e);}}else if(pendingMicrophoneId!=null){error(id,new Exception("A microphone permission request is already open."));}else{pendingMicrophoneId=id;requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},8);}return;}if(method.equals("connect")){connect();return;}if(method.equals("cancel")){ai.cancel();return;}if(method.equals("usage")){startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://chatgpt.com/settings/usage")));return;}if(method.equals("models")){worker.execute(()->{try{JSONArray models=ai.models();String[] labels=new String[models.length()];for(int i=0;i<labels.length;i++)labels[i]=models.getJSONObject(i).getString("display_name");runOnUiThread(()->new AlertDialog.Builder(MainActivity.this).setTitle("ChatGPT model").setItems(labels,(d,index)->worker.execute(()->{try{ai.chooseModel(models.getJSONObject(index).getString("slug"));state();}catch(Exception e){error("account",e);}})).show());}catch(Exception e){error("account",e);}});return;}worker.execute(()->{try{JSONObject out;if(method.equals("status"))out=ai.status();else if(method.equals("ask"))out=ai.ask(new JSONObject(payload));else if(method.equals("signout")){ai.signOut();out=new JSONObject().put("connected",false);state();}else throw new Exception("Unsupported native request.");result(id,out);}catch(Exception e){error(id,e);}});});}
  @JavascriptInterface public void listen(String id){runOnUiThread(()->{if(!trusted()||!foreground)return;if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){speechEvent(id,"error","not-allowed",false);speechEvent(id,"end","",false);return;}destroySpeech();if(!SpeechRecognizer.isRecognitionAvailable(MainActivity.this)){speechEvent(id,"error","service-not-allowed",false);speechEvent(id,"end","",false);return;}speechId=id;speech=SpeechRecognizer.createSpeechRecognizer(MainActivity.this);speech.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){speechEvent(id,"start","",false);}public void onBeginningOfSpeech(){}public void onRmsChanged(float f){}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){}public void onEvent(int type,Bundle b){}public void onError(int code){speechEvent(id,"error",code==SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS?"not-allowed":code==SpeechRecognizer.ERROR_AUDIO?"audio-capture":code==SpeechRecognizer.ERROR_RECOGNIZER_BUSY?"busy":code==SpeechRecognizer.ERROR_NETWORK||code==SpeechRecognizer.ERROR_NETWORK_TIMEOUT?"network":code==SpeechRecognizer.ERROR_NO_MATCH||code==SpeechRecognizer.ERROR_SPEECH_TIMEOUT?"no-speech":"aborted",false);speechEvent(id,"end","",false);}public void onResults(Bundle b){deliver(b,true);speechEvent(id,"end","",false);}public void onPartialResults(Bundle b){deliver(b,false);}private void deliver(Bundle b,boolean last){ArrayList<String> texts=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(texts!=null&&!texts.isEmpty())speechEvent(id,"result",texts.get(0),last);}});Intent intent=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);intent.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);intent.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"en-US");intent.putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true);try{speech.startListening(intent);}catch(Exception e){speechEvent(id,"error","audio-capture",false);speechEvent(id,"end","",false);}});}
  @JavascriptInterface public void stopListening(String id){runOnUiThread(()->{if(id!=null&&id.equals(speechId)){destroySpeech();speechEvent(id,"end","",false);}});}
 }
 private void speechEvent(String id,String type,String text,boolean last){if(!trusted())return;web.evaluateJavascript("window.jarvisNativeSpeech?.("+JSONObject.quote(id)+","+JSONObject.quote(type)+","+JSONObject.quote(text)+","+last+");",null);}
 private void destroySpeech(){if(speech!=null){speech.cancel();speech.destroy();speech=null;}speechId=null;}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==8&&pendingMicrophoneId!=null){String id=pendingMicrophoneId;pendingMicrophoneId=null;if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED){try{result(id,new JSONObject().put("granted",true));}catch(JSONException e){error(id,e);}}else error(id,new Exception("Microphone permission was declined. Tap Start JARVIS to allow it."));}if(r==7&&pendingPermission!=null){if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)pendingPermission.grant(new String[]{PermissionRequest.RESOURCE_AUDIO_CAPTURE});else pendingPermission.deny();pendingPermission=null;}}
 private void welcome(){if(welcomeShowing||getPreferences(0).getBoolean("plan-welcome",false))return;welcomeShowing=true;new AlertDialog.Builder(this).setTitle("You’re using your ChatGPT plan").setMessage("Eligible JARVIS requests use your existing ChatGPT plan allowance. Manage app limits in ChatGPT Settings → Usage. Keep extra-credit use and automatic credit purchases off to prevent additional charges.").setPositiveButton("Got it",(d,w)->{getPreferences(0).edit().putBoolean("plan-welcome",true).apply();welcomeShowing=false;}).setOnCancelListener(d->welcomeShowing=false).show();}
 private void notice(String message){runOnUiThread(()->{if(trusted())web.evaluateJavascript("window.dispatchEvent(new CustomEvent('jarvis-native-notice',{detail:"+JSONObject.quote(message)+"}));",null);});}
 private void finishSignIn(){if(!foreground||authFinishing)return;authFinishing=true;worker.execute(()->{try{if(!foreground)return;if(ai.hasStagedCallback()){notice("Finishing ChatGPT sign-in. Keep JARVIS open…");ai.finishAuthorization();notice("ChatGPT connected. Tap Start JARVIS.");}if(ai.status().optBoolean("connected"))runOnUiThread(()->{if(foreground)welcome();});}catch(Exception e){error("account",e);}finally{runOnUiThread(()->{authFinishing=false;state();});}});}
 protected void onResume(){super.onResume();foreground=true;getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(web!=null){web.onResume();finishSignIn();web.evaluateJavascript("window.jarvisNativeResume?.();",null);state();}}
 protected void onPause(){foreground=false;if(web!=null){web.evaluateJavascript("window.jarvisNativePause?.();",null);web.onPause();}destroySpeech();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);super.onPause();}
 protected void onDestroy(){if(pendingPermission!=null)pendingPermission.deny();destroySpeech();if(ai!=null)ai.cancel();worker.shutdownNow();if(site!=null)site.close();if(web!=null){web.removeJavascriptInterface("JarvisNative");web.destroy();}super.onDestroy();}
}
